package hu.synostream.android;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.util.regex.Pattern;import static org.junit.Assert.*;
/** Public TMDB reference on a test-owned NAS; never imports an actual user's inventory or credentials. */
@RunWith(AndroidJUnit4.class)
public class SeriesPreview050Test {
    @Test public void actualSeriesPagesMatchOverviewSeasonAndEpisodeStructure()throws Exception{
        android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();android.content.Context context=instrumentation.getTargetContext();JSONObject reference;try(InputStream in=instrumentation.getContext().getAssets().open("tv_reference.json")){reference=new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));}JSONObject info=reference.getJSONObject("info"),season=reference.getJSONObject("season");Android050FlowTest flow=new Android050FlowTest();
        try(FakeNas nas=new FakeNas()){try{
            nas.folders.add("/Series/Reference");JSONArray seasons=info.getJSONArray("seasons");for(int n=0;n<seasons.length();n++){JSONObject group=seasons.getJSONObject(n);int number=group.optInt("season_number");if(number<=0)continue;String directory=String.format(Locale.ROOT,"/Series/Reference/Season%02d",number);nas.folders.add(directory);for(int e=1;e<=group.optInt("episode_count");e++)nas.files.put(directory+String.format(Locale.ROOT,"/S%02dE%02d.mkv",number,e),new byte[]{1,2,3});}
            Library.Card card=new Library.Card("/Series/Reference",info.getString("name"),false);card.episodeRoots.add(card.path);Library.apply(card,info);flow.setup(nas,List.of(card));flow.app.store.secret("tmdb_key","fixture-cache-key");new MetadataCache(context).put("recognition-v2:tv/60059/season/4?language=hu-HU",season);
            MainActivity activity=flow.activity();instrumentation.runOnMainSync(()->{flow.app.page="shows";JSONObject lib=LibraryConfig.defaultLibrary(flow.app.libraries,false);try{LibraryConfig.paths(lib,List.of("/Series"));}catch(Exception error){throw new RuntimeException(error);}flow.app.selectedLibrary=lib.optString("id");activity.invalidatePage();});UiDevice device=flow.device;assertTrue(device.wait(Until.hasObject(By.desc(card.title)),10000));device.findObject(By.desc(card.title)).click();assertTrue(device.wait(Until.hasObject(By.desc("Sorozat áttekintése")),10000));waitPicture(card.poster);waitPicture(card.backdrop);device.waitForIdle();assertTrue(device.takeScreenshot(new File(context.getFilesDir(),"050-series-overview.png")));
            device.findObject(By.desc("Sorozat epizódjai")).click();assertTrue(device.wait(Until.hasObject(By.text(Pattern.compile(".*4\\. évad"))),10000));device.waitForIdle();assertTrue(device.takeScreenshot(new File(context.getFilesDir(),"050-series-seasons.png")));device.findObject(By.text(Pattern.compile(".*4\\. évad"))).click();String name=season.getJSONArray("episodes").getJSONObject(0).getString("name");assertTrue(device.wait(Until.hasObject(By.text(name)),10000));for(int n=0;n<3;n++){String still=season.getJSONArray("episodes").getJSONObject(n).optString("still_path");if(still.startsWith("/"))waitPicture("https://image.tmdb.org/t/p/w300"+still);}device.waitForIdle();assertTrue(device.takeScreenshot(new File(context.getFilesDir(),"050-series-episodes.png")));
            device.setOrientationLeft();long rotationDeadline=android.os.SystemClock.elapsedRealtime()+10000;while((flow.activity()==activity||flow.activity().getResources().getConfiguration().orientation!=android.content.res.Configuration.ORIENTATION_LANDSCAPE)&&android.os.SystemClock.elapsedRealtime()<rotationDeadline)Thread.sleep(50);assertNotSame("Rotation must create the new Activity before checking its detail window",activity,flow.activity());assertTrue("Episode tab must exist in the recreated window",device.wait(Until.hasObject(By.desc("Sorozat epizódjai")),10000));device.waitForIdle();assertTrue("Expanded season episode must be restored in landscape",device.wait(Until.hasObject(By.text(name)),10000));assertTrue(device.takeScreenshot(new File(context.getFilesDir(),"050-series-landscape.png")));
        }finally{flow.cleanup();}}
    }
    private void waitPicture(String url)throws Exception{if(url.isEmpty())return;java.lang.reflect.Field f=MainActivity.class.getDeclaredField("pictures");f.setAccessible(true);android.util.LruCache<?,?> cache=(android.util.LruCache<?,?>)f.get(null);long end=System.currentTimeMillis()+15000;while(!cache.snapshot().containsKey(url)&&System.currentTimeMillis()<end)Thread.sleep(100);}
}
